function Pill({ children, tone = "info" }: { children: ReactNode; tone?: Tone }) {
  return <span className={`com-pill tone-${tone}`}><i />{children}</span>;
}

function Head({ eyebrow, title, side }: { eyebrow: string; title: string; side?: ReactNode }) {
  return <div className="com-head"><div><span>{eyebrow}</span><h2>{title}</h2></div>{side}</div>;
}

function ReachMap({ props, expanded = false }: { props: CommunicationsModuleProps; expanded?: boolean }) {
  const mapLayers = [
    ["territory", "Área de impacto", "TS-081 · 3,8 km²"],
    ["receptors", "Públicos e receptores", "4.820 · 8 críticos"],
    ["assets", "Serviços e rotas", "V-EXT-04 · C-07"],
    ["risk", "Lacunas de entrega", "126 destinatários"],
    ["geobases", "Instituições", "7 pontos focais"],
    ["landCover", "Sentinel-2 Land Cover", "ArcGIS Living Atlas"],
  ];
  return <article className={`panel com-map-card ${expanded ? "expanded" : ""}`}>
    <Head eyebrow="ARCGIS · COMMUNICATION REACH" title="Quem está dentro da área e recebeu a mensagem?" side={<Pill tone={props.mapStatus.includes("Online") ? "ok" : "watch"}>{props.mapStatus}</Pill>} />
    <div className="com-map-shell">
      {props.renderMap()}
      <div className="com-map-layers">{mapLayers.map(([key,label,note]) => <label key={key}><input type="checkbox" checked={Boolean(props.layers[key])} onChange={() => props.onToggleLayer(key)} /><i className={`layer-${key}`} /><span><b>{label}</b><small>{note}</small></span></label>)}</div>
      <button className="com-map-callout" onClick={() => props.onToast("PUB-01 aberto · cobertura, canais, falhas e contatos protegidos") }><Pill tone="critical">PUB-01</Pill><strong>Comunidade C-07</strong><span>2.940 pessoas · 92% entrega</span><small>38 sem canal digital · rota de campo ativada</small></button>
      <div className="com-map-legend"><span><i className="planned" />Planejado</span><span><i className="delivered" />Entregue</span><span><i className="gap" />Lacuna</span></div>
    </div>
  </article>;
}

