      <div className="com-command-state"><Pill tone={props.scenarioStep >= 5 ? "ok" : "critical"}>{props.scenarioStep >= 5 ? "APROVADO" : "APROVAÇÃO REQUERIDA"}</Pill><strong>{props.stage.time} · {props.stage.label}</strong><small>{props.stage.note}</small></div>
