  if (mode === "Instituições & Contatos") return <Contacts props={props} />;
  const current=audiences.find(row=>row[0]===selected)??audiences[0];
  return <div className="com-view"><section className="com-view-heading"><div><span>AUDIENCE INTELLIGENCE · LGPD BY DESIGN</span><h2>Públicos geográficos, operacionais e institucionais</h2><p>Segmentação por finalidade e necessidade; contato nominal protegido e acesso auditado.</p></div><button className="primary" onClick={()=>props.onToast("Novo público: finalidade, regra espacial, canais, retenção e owner")}>＋ Novo público</button></section><section className="com-audience-grid"><article className="panel com-audience-list"><Head eyebrow="PRIORITY AUDIENCES" title="12 públicos · 5 críticos" />{audiences.map(row=><button className={selected===row[0]?"selected":""} key={row[0]} onClick={()=>setSelected(row[0])}><span>{row[0]}</span><p><b>{row[1]}</b><small>{row[3]}</small></p><strong>{row[2]}</strong><Pill tone={row[5] as Tone}>{row[4]}</Pill></button>)}</article><article className="panel com-audience-cockpit"><Head eyebrow="AUDIENCE COCKPIT" title={`${current[0]} · ${current[1]}`} side={<Pill tone="critical">PRIORIDADE 1</Pill>} /><div className="com-audience-facts">{[["Estimativa",current[2]],["Planejado","2.894"],["Entregue","2.706"],["Confirmado","2.354"],["Sem canal","38"],["Idioma","PT-BR"]].map(row=><div key={row[0]}><span>{row[0]}</span><strong>{row[1]}</strong></div>)}</div><div className="com-rule"><span>REGRA DE INCLUSÃO</span><code>intersects(TS-081) AND residence=C-07 AND active=true</code><small>Snapshot 19:46 · ArcGIS GeoEvent · estimate, não contagem censitária.</small></div><div className="com-channel-bars">{[["SMS",92],["WhatsApp inst.",84],["Voz",31],["Campo",8]].map(row=><div key={row[0]}><span>{row[0]}</span><i><strong style={{width:`${row[1]}%`}} /></i><b>{row[1]}%</b></div>)}</div><div className="com-actions"><button onClick={props.onTerritory}>Receptores M9</button><button onClick={()=>props.onToast("Privacy impact e fundamento legal abertos")}>Privacy check</button><button className="primary" onClick={()=>props.onToast("PUB-01 adicionado ao alerta ALT-118")}>Usar no alerta</button></div></article></section></div>;
